-- ============================================================================
-- FBSF Website — MySQL Database Schema (Redesigned Website)
-- Faculty of Business Studies and Finance, Wayamba University of Sri Lanka
-- ----------------------------------------------------------------------------
-- Generated by tools/build_database_sql.py from verified site content.
-- Compatible with MySQL 5.7+ / 8.0 (utf8mb4, InnoDB).
-- Import:  mysql -u user -p < database/website_database.sql
--          (or phpMyAdmin: import this file)
-- Security: passwords are bcrypt-hashed; no credentials or secrets stored.
-- ============================================================================

DROP DATABASE IF EXISTS `fbsf_website`;
CREATE DATABASE `fbsf_website`
    CHARACTER SET utf8mb4
    COLLATE utf8mb4_unicode_ci;
USE `fbsf_website`;

-- ----------------------------------------------------------------------------
-- 1. RBAC — roles, permissions, users
-- ----------------------------------------------------------------------------

CREATE TABLE `roles` (
    `id`          TINYINT UNSIGNED NOT NULL AUTO_INCREMENT,
    `name`        VARCHAR(50)  NOT NULL,
    `description` VARCHAR(255) DEFAULT NULL,
    `created_at`  DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`),
    UNIQUE KEY `uk_roles_name` (`name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `permissions` (
    `id`            TINYINT UNSIGNED NOT NULL AUTO_INCREMENT,
    `permission_key` VARCHAR(100) NOT NULL,
    `description`   VARCHAR(255) DEFAULT NULL,
    `created_at`    DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`),
    UNIQUE KEY `uk_permissions_key` (`permission_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `role_permissions` (
    `role_id`       TINYINT UNSIGNED NOT NULL,
    `permission_id` TINYINT UNSIGNED NOT NULL,
    `created_at`    DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (`role_id`, `permission_id`),
    KEY `idx_role_permissions_perm` (`permission_id`),
    CONSTRAINT `fk_role_permissions_role`
        FOREIGN KEY (`role_id`) REFERENCES `roles` (`id`) ON DELETE CASCADE,
    CONSTRAINT `fk_role_permissions_perm`
        FOREIGN KEY (`permission_id`) REFERENCES `permissions` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `users` (
    `id`            INT UNSIGNED NOT NULL AUTO_INCREMENT,
    `username`      VARCHAR(50)  NOT NULL,
    `email`         VARCHAR(190) NOT NULL,
    `password_hash` VARCHAR(255) NOT NULL COMMENT 'bcrypt hash — never plain text',
    `full_name`     VARCHAR(100) DEFAULT NULL,
    `role_id`       TINYINT UNSIGNED NOT NULL,
    `is_active`     TINYINT(1)   NOT NULL DEFAULT 1,
    `last_login_at` DATETIME     DEFAULT NULL,
    `created_at`    DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `updated_at`    DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`),
    UNIQUE KEY `uk_users_username` (`username`),
    UNIQUE KEY `uk_users_email` (`email`),
    KEY `idx_users_role` (`role_id`),
    CONSTRAINT `fk_users_role`
        FOREIGN KEY (`role_id`) REFERENCES `roles` (`id`) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ----------------------------------------------------------------------------
-- 2. Pages & navigation
-- ----------------------------------------------------------------------------

CREATE TABLE `pages` (
    `id`              INT UNSIGNED NOT NULL AUTO_INCREMENT,
    `slug`            VARCHAR(190) NOT NULL,
    `title`           VARCHAR(255) NOT NULL,
    `path`            VARCHAR(255) NOT NULL,
    `template`        VARCHAR(100) NOT NULL DEFAULT 'default',
    `meta_title`      VARCHAR(255) DEFAULT NULL,
    `meta_description` VARCHAR(512) DEFAULT NULL,
    `sort_order`      INT NOT NULL DEFAULT 0,
    `is_published`    TINYINT(1)   NOT NULL DEFAULT 1,
    `created_at`      DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `updated_at`      DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`),
    UNIQUE KEY `uk_pages_slug` (`slug`),
    KEY `idx_pages_path` (`path`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `menus` (
    `id`         INT UNSIGNED NOT NULL AUTO_INCREMENT,
    `name`       VARCHAR(100) NOT NULL,
    `location`   VARCHAR(50)  NOT NULL DEFAULT 'header' COMMENT 'header, footer, sidebar',
    `created_at` DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`),
    UNIQUE KEY `uk_menus_name` (`name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `menu_items` (
    `id`          INT UNSIGNED NOT NULL AUTO_INCREMENT,
    `menu_id`     INT UNSIGNED NOT NULL,
    `parent_id`   INT UNSIGNED DEFAULT NULL COMMENT 'self-reference for dropdowns',
    `page_id`     INT UNSIGNED DEFAULT NULL,
    `title`       VARCHAR(255) NOT NULL,
    `url`         VARCHAR(512) NOT NULL DEFAULT '#',
    `target`      VARCHAR(20)  NOT NULL DEFAULT '_self',
    `sort_order`  INT NOT NULL DEFAULT 0,
    `is_published` TINYINT(1) NOT NULL DEFAULT 1,
    `created_at`  DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`),
    KEY `idx_menu_items_menu` (`menu_id`, `sort_order`),
    KEY `idx_menu_items_parent` (`parent_id`),
    KEY `idx_menu_items_page` (`page_id`),
    CONSTRAINT `fk_menu_items_menu`
        FOREIGN KEY (`menu_id`) REFERENCES `menus` (`id`) ON DELETE CASCADE,
    CONSTRAINT `fk_menu_items_parent`
        FOREIGN KEY (`parent_id`) REFERENCES `menu_items` (`id`) ON DELETE CASCADE,
    CONSTRAINT `fk_menu_items_page`
        FOREIGN KEY (`page_id`) REFERENCES `pages` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ----------------------------------------------------------------------------
-- 3. Departments
-- ----------------------------------------------------------------------------

CREATE TABLE `departments` (
    `id`            INT UNSIGNED NOT NULL AUTO_INCREMENT,
    `slug`          VARCHAR(190) NOT NULL,
    `name`          VARCHAR(255) NOT NULL,
    `abbreviation`  VARCHAR(20)  DEFAULT NULL,
    `tagline`       VARCHAR(255) DEFAULT NULL,
    `intro`         TEXT,
    `vision`        TEXT,
    `mission`       TEXT,
    `hod_name`      VARCHAR(100) DEFAULT NULL,
    `hod_title`     VARCHAR(100) DEFAULT NULL,
    `hod_message`   TEXT,
    `research`      TEXT,
    `contact_email` VARCHAR(190) DEFAULT NULL,
    `contact_phone` VARCHAR(50)  DEFAULT NULL,
    `is_published`  TINYINT(1)   NOT NULL DEFAULT 1,
    `sort_order`    INT NOT NULL DEFAULT 0,
    `created_at`    DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `updated_at`    DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`),
    UNIQUE KEY `uk_departments_slug` (`slug`),
    KEY `idx_departments_name` (`name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `department_partners` (
    `id`            INT UNSIGNED NOT NULL AUTO_INCREMENT,
    `department_id` INT UNSIGNED NOT NULL,
    `partner_name`  VARCHAR(255) NOT NULL DEFAULT '',
    `detail`        TEXT,
    `sort_order`    INT NOT NULL DEFAULT 0,
    `created_at`    DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`),
    KEY `idx_dept_partners_dept` (`department_id`),
    CONSTRAINT `fk_dept_partners_dept`
        FOREIGN KEY (`department_id`) REFERENCES `departments` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ----------------------------------------------------------------------------
-- 4. Programmes
-- ----------------------------------------------------------------------------

CREATE TABLE `programme_categories` (
    `id`         TINYINT UNSIGNED NOT NULL AUTO_INCREMENT,
    `slug`       VARCHAR(100) NOT NULL,
    `name`       VARCHAR(100) NOT NULL,
    `sort_order` INT NOT NULL DEFAULT 0,
    PRIMARY KEY (`id`),
    UNIQUE KEY `uk_programme_cat_slug` (`slug`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `programmes` (
    `id`                  INT UNSIGNED NOT NULL AUTO_INCREMENT,
    `slug`                VARCHAR(190) NOT NULL,
    `name`                VARCHAR(255) NOT NULL,
    `category_id`         TINYINT UNSIGNED DEFAULT NULL,
    `department_id`       INT UNSIGNED DEFAULT NULL,
    `summary`             TEXT,
    `description`         TEXT,
    `duration`            VARCHAR(100) DEFAULT NULL,
    `credits`             VARCHAR(50)  DEFAULT NULL,
    `fees`                TEXT,
    `deadline`            VARCHAR(100) DEFAULT NULL,
    `deadline_status`     ENUM('historical','upcoming','none') NOT NULL DEFAULT 'historical'
                          COMMENT 'historical dates never shown as upcoming',
    `application_contact` TEXT,
    `entry_requirements`  TEXT,
    `highlights`          TEXT,
    `document_note`       TEXT,
    `is_published`        TINYINT(1)   NOT NULL DEFAULT 1,
    `sort_order`          INT NOT NULL DEFAULT 0,
    `created_at`          DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `updated_at`          DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`),
    UNIQUE KEY `uk_programmes_slug` (`slug`),
    KEY `idx_programmes_category` (`category_id`),
    KEY `idx_programmes_department` (`department_id`),
    KEY `idx_programmes_deadline_status` (`deadline_status`),
    CONSTRAINT `fk_programmes_category`
        FOREIGN KEY (`category_id`) REFERENCES `programme_categories` (`id`) ON DELETE SET NULL,
    CONSTRAINT `fk_programmes_department`
        FOREIGN KEY (`department_id`) REFERENCES `departments` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `programme_entry_requirements` (
    `id`            INT UNSIGNED NOT NULL AUTO_INCREMENT,
    `programme_id`  INT UNSIGNED NOT NULL,
    `requirement`   TEXT NOT NULL,
    `sort_order`    INT NOT NULL DEFAULT 0,
    `created_at`    DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`),
    KEY `idx_prog_entry_prog` (`programme_id`),
    CONSTRAINT `fk_prog_entry_prog`
        FOREIGN KEY (`programme_id`) REFERENCES `programmes` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `programme_courses` (
    `id`            INT UNSIGNED NOT NULL AUTO_INCREMENT,
    `programme_id`  INT UNSIGNED NOT NULL,
    `semester`      VARCHAR(50)  DEFAULT NULL,
    `course_code`   VARCHAR(50)  DEFAULT NULL,
    `course_title`  VARCHAR(255) NOT NULL,
    `credits`       VARCHAR(20)  DEFAULT NULL,
    `sort_order`    INT NOT NULL DEFAULT 0,
    `created_at`    DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`),
    KEY `idx_prog_courses_prog` (`programme_id`),
    CONSTRAINT `fk_prog_courses_prog`
        FOREIGN KEY (`programme_id`) REFERENCES `programmes` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ----------------------------------------------------------------------------
-- 5. Journals & articles
-- ----------------------------------------------------------------------------

CREATE TABLE `journals` (
    `id`                  INT UNSIGNED NOT NULL AUTO_INCREMENT,
    `slug`                VARCHAR(190) NOT NULL,
    `abbreviation`        VARCHAR(50)  DEFAULT NULL,
    `name`                VARCHAR(255) NOT NULL,
    `type`                VARCHAR(100) DEFAULT NULL,
    `publisher`           VARCHAR(255) DEFAULT NULL,
    `issn`                VARCHAR(30)  DEFAULT NULL,
    `frequency`           VARCHAR(100) DEFAULT NULL,
    `description`         TEXT,
    `submission_guidelines` TEXT,
    `submission_email`    VARCHAR(190) DEFAULT NULL,
    `latest_issue`        VARCHAR(255) DEFAULT NULL,
    `is_published`        TINYINT(1)   NOT NULL DEFAULT 1,
    `sort_order`          INT NOT NULL DEFAULT 0,
    `created_at`          DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `updated_at`          DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`),
    UNIQUE KEY `uk_journals_slug` (`slug`),
    KEY `idx_journals_name` (`name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `journal_issues` (
    `id`          INT UNSIGNED NOT NULL AUTO_INCREMENT,
    `journal_id`  INT UNSIGNED NOT NULL,
    `year_volume` VARCHAR(100) DEFAULT NULL,
    `detail`      VARCHAR(255) DEFAULT NULL,
    `sort_order`  INT NOT NULL DEFAULT 0,
    `created_at`  DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`),
    KEY `idx_journal_issues_journal` (`journal_id`),
    CONSTRAINT `fk_journal_issues_journal`
        FOREIGN KEY (`journal_id`) REFERENCES `journals` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `editorial_board_members` (
    `id`         INT UNSIGNED NOT NULL AUTO_INCREMENT,
    `journal_id` INT UNSIGNED NOT NULL,
    `role`       VARCHAR(100) NOT NULL DEFAULT '',
    `name`       VARCHAR(255) NOT NULL DEFAULT '',
    `sort_order` INT NOT NULL DEFAULT 0,
    `created_at` DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`),
    KEY `idx_editorial_journal` (`journal_id`),
    CONSTRAINT `fk_editorial_journal`
        FOREIGN KEY (`journal_id`) REFERENCES `journals` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `articles` (
    `id`          INT UNSIGNED NOT NULL AUTO_INCREMENT,
    `journal_id`  INT UNSIGNED NOT NULL,
    `title`       VARCHAR(512) NOT NULL,
    `authors`     TEXT,
    `issue`       VARCHAR(255) DEFAULT NULL,
    `description` TEXT,
    `created_at`  DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`),
    KEY `idx_articles_journal` (`journal_id`),
    KEY `idx_articles_title` (`title`),
    CONSTRAINT `fk_articles_journal`
        FOREIGN KEY (`journal_id`) REFERENCES `journals` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ----------------------------------------------------------------------------
-- 6. Events & symposia
-- ----------------------------------------------------------------------------

CREATE TABLE `event_types` (
    `id`         TINYINT UNSIGNED NOT NULL AUTO_INCREMENT,
    `slug`       VARCHAR(100) NOT NULL,
    `name`       VARCHAR(100) NOT NULL,
    `sort_order` INT NOT NULL DEFAULT 0,
    PRIMARY KEY (`id`),
    UNIQUE KEY `uk_event_types_slug` (`slug`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `events` (
    `id`             INT UNSIGNED NOT NULL AUTO_INCREMENT,
    `slug`           VARCHAR(190) NOT NULL,
    `event_type_id`  TINYINT UNSIGNED NOT NULL,
    `edition`        VARCHAR(50)  DEFAULT NULL,
    `name`           VARCHAR(255) NOT NULL,
    `organiser`      VARCHAR(255) DEFAULT NULL,
    `theme`          VARCHAR(255) DEFAULT NULL,
    `description`    TEXT,
    `status`         ENUM('past','upcoming','archived') NOT NULL DEFAULT 'past'
                     COMMENT 'past events must never display as upcoming',
    `submission_info` TEXT,
    `contact`        TEXT,
    `keynote_name`   VARCHAR(255) DEFAULT NULL,
    `keynote_details` TEXT,
    `is_published`   TINYINT(1)   NOT NULL DEFAULT 1,
    `sort_order`     INT NOT NULL DEFAULT 0,
    `created_at`     DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `updated_at`     DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`),
    UNIQUE KEY `uk_events_slug` (`slug`),
    KEY `idx_events_type` (`event_type_id`),
    KEY `idx_events_status` (`status`),
    CONSTRAINT `fk_events_type`
        FOREIGN KEY (`event_type_id`) REFERENCES `event_types` (`id`) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `event_tracks` (
    `id`        INT UNSIGNED NOT NULL AUTO_INCREMENT,
    `event_id`  INT UNSIGNED NOT NULL,
    `title`     VARCHAR(255) NOT NULL,
    `sort_order` INT NOT NULL DEFAULT 0,
    `created_at` DATETIME    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`),
    KEY `idx_event_tracks_event` (`event_id`),
    CONSTRAINT `fk_event_tracks_event`
        FOREIGN KEY (`event_id`) REFERENCES `events` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `event_dates` (
    `id`         INT UNSIGNED NOT NULL AUTO_INCREMENT,
    `event_id`   INT UNSIGNED NOT NULL,
    `label`      VARCHAR(255) NOT NULL DEFAULT '',
    `event_date` VARCHAR(100) DEFAULT NULL,
    `sort_order` INT NOT NULL DEFAULT 0,
    `created_at` DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`),
    KEY `idx_event_dates_event` (`event_id`),
    CONSTRAINT `fk_event_dates_event`
        FOREIGN KEY (`event_id`) REFERENCES `events` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `event_committee` (
    `id`        INT UNSIGNED NOT NULL AUTO_INCREMENT,
    `event_id`  INT UNSIGNED NOT NULL,
    `role`      VARCHAR(100) NOT NULL DEFAULT '',
    `name`      VARCHAR(255) NOT NULL DEFAULT '',
    `contact`   VARCHAR(190) DEFAULT NULL,
    `sort_order` INT NOT NULL DEFAULT 0,
    `created_at` DATETIME    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`),
    KEY `idx_event_committee_event` (`event_id`),
    CONSTRAINT `fk_event_committee_event`
        FOREIGN KEY (`event_id`) REFERENCES `events` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `event_downloads` (
    `id`        INT UNSIGNED NOT NULL AUTO_INCREMENT,
    `event_id`  INT UNSIGNED NOT NULL,
    `title`     VARCHAR(255) NOT NULL,
    `note`      VARCHAR(255) DEFAULT NULL,
    `sort_order` INT NOT NULL DEFAULT 0,
    `created_at` DATETIME    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`),
    KEY `idx_event_downloads_event` (`event_id`),
    CONSTRAINT `fk_event_downloads_event`
        FOREIGN KEY (`event_id`) REFERENCES `events` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ----------------------------------------------------------------------------
-- 7. News & announcements
-- ----------------------------------------------------------------------------

CREATE TABLE `news_categories` (
    `id`         TINYINT UNSIGNED NOT NULL AUTO_INCREMENT,
    `slug`       VARCHAR(100) NOT NULL,
    `name`       VARCHAR(100) NOT NULL,
    `sort_order` INT NOT NULL DEFAULT 0,
    PRIMARY KEY (`id`),
    UNIQUE KEY `uk_news_cat_slug` (`slug`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `news` (
    `id`           INT UNSIGNED NOT NULL AUTO_INCREMENT,
    `slug`         VARCHAR(190) NOT NULL,
    `news_type`    ENUM('news','announcement') NOT NULL DEFAULT 'announcement',
    `category_id`  TINYINT UNSIGNED DEFAULT NULL,
    `title`        VARCHAR(255) NOT NULL,
    `body`         TEXT NOT NULL,
    `status`       ENUM('published','draft') NOT NULL DEFAULT 'published',
    `is_archived`  TINYINT(1)   NOT NULL DEFAULT 0 COMMENT 'archived items never shown as upcoming',
    `published_at` DATETIME     DEFAULT NULL,
    `sort_order`   INT NOT NULL DEFAULT 0,
    `created_at`   DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `updated_at`   DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`),
    UNIQUE KEY `uk_news_slug` (`slug`),
    KEY `idx_news_category` (`category_id`),
    KEY `idx_news_status` (`status`),
    KEY `idx_news_published_at` (`published_at`),
    CONSTRAINT `fk_news_category`
        FOREIGN KEY (`category_id`) REFERENCES `news_categories` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ----------------------------------------------------------------------------
-- 8. Downloads
-- ----------------------------------------------------------------------------

CREATE TABLE `downloads` (
    `id`            INT UNSIGNED NOT NULL AUTO_INCREMENT,
    `slug`          VARCHAR(190) NOT NULL,
    `name`          VARCHAR(255) NOT NULL,
    `file_name`     VARCHAR(255) DEFAULT NULL,
    `category`      VARCHAR(100) DEFAULT NULL,
    `description`   TEXT,
    `is_published`  TINYINT(1)   NOT NULL DEFAULT 1,
    `sort_order`    INT NOT NULL DEFAULT 0,
    `created_at`    DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`),
    UNIQUE KEY `uk_downloads_slug` (`slug`),
    KEY `idx_downloads_category` (`category`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ----------------------------------------------------------------------------
-- 9. FAQs
-- ----------------------------------------------------------------------------

CREATE TABLE `faqs` (
    `id`           INT UNSIGNED NOT NULL AUTO_INCREMENT,
    `question`     VARCHAR(255) NOT NULL,
    `answer`       TEXT NOT NULL,
    `sort_order`   INT NOT NULL DEFAULT 0,
    `is_published` TINYINT(1)   NOT NULL DEFAULT 1,
    `created_at`   DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ----------------------------------------------------------------------------
-- 10. Contacts & messages
-- ----------------------------------------------------------------------------

CREATE TABLE `contact_groups` (
    `id`             INT UNSIGNED NOT NULL AUTO_INCREMENT,
    `group_name`     VARCHAR(100) NOT NULL,
    `contact_person` VARCHAR(255) DEFAULT NULL,
    `email`          VARCHAR(190) DEFAULT NULL,
    `phone`          VARCHAR(50)  DEFAULT NULL,
    `sort_order`     INT NOT NULL DEFAULT 0,
    `created_at`     DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `contact_messages` (
    `id`         INT UNSIGNED NOT NULL AUTO_INCREMENT,
    `name`       VARCHAR(100)  NOT NULL,
    `email`      VARCHAR(190)  NOT NULL,
    `phone`      VARCHAR(50)   DEFAULT NULL,
    `subject`    VARCHAR(255)  DEFAULT NULL,
    `message`    TEXT NOT NULL,
    `status`     ENUM('new','read','replied','spam') NOT NULL DEFAULT 'new',
    `user_id`    INT UNSIGNED  DEFAULT NULL COMMENT 'staff member who replied',
    `created_at` DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `updated_at` DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`),
    KEY `idx_contact_messages_status` (`status`),
    KEY `idx_contact_messages_email` (`email`),
    KEY `idx_contact_messages_created` (`created_at`),
    CONSTRAINT `fk_contact_messages_user`
        FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ----------------------------------------------------------------------------
-- 11. Media library
-- ----------------------------------------------------------------------------

CREATE TABLE `media` (
    `id`           INT UNSIGNED NOT NULL AUTO_INCREMENT,
    `file_name`    VARCHAR(255) NOT NULL,
    `file_path`    VARCHAR(512) NOT NULL,
    `mime_type`    VARCHAR(100) DEFAULT NULL,
    `file_size`    INT UNSIGNED DEFAULT NULL,
    `media_type`   ENUM('image','document','video','other') NOT NULL DEFAULT 'image',
    `alt_text`     VARCHAR(512) DEFAULT NULL,
    `uploaded_by`  INT UNSIGNED DEFAULT NULL,
    `created_at`   DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`),
    KEY `idx_media_type` (`media_type`),
    KEY `idx_media_uploaded_by` (`uploaded_by`),
    CONSTRAINT `fk_media_uploaded_by`
        FOREIGN KEY (`uploaded_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ----------------------------------------------------------------------------
-- 12. Site content blocks (history, quick links, research areas, committees)
-- ----------------------------------------------------------------------------

CREATE TABLE `history_timeline` (
    `id`          INT UNSIGNED NOT NULL AUTO_INCREMENT,
    `event_date`  VARCHAR(100) DEFAULT NULL,
    `title`       VARCHAR(255) NOT NULL,
    `description` TEXT,
    `sort_order`  INT NOT NULL DEFAULT 0,
    PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `quick_links` (
    `id`          INT UNSIGNED NOT NULL AUTO_INCREMENT,
    `title`       VARCHAR(100) NOT NULL,
    `url`         VARCHAR(512) NOT NULL,
    `icon`        VARCHAR(50)  DEFAULT NULL,
    `description` VARCHAR(255) DEFAULT NULL,
    `sort_order`  INT NOT NULL DEFAULT 0,
    PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `research_areas` (
    `id`         INT UNSIGNED NOT NULL AUTO_INCREMENT,
    `name`       VARCHAR(100) NOT NULL,
    `sort_order` INT NOT NULL DEFAULT 0,
    PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `faculty_committees` (
    `id`          INT UNSIGNED NOT NULL AUTO_INCREMENT,
    `title`       VARCHAR(255) NOT NULL,
    `description` TEXT,
    `sort_order`  INT NOT NULL DEFAULT 0,
    PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ----------------------------------------------------------------------------
-- 13. Site settings (key-value)
-- ----------------------------------------------------------------------------

CREATE TABLE `site_settings` (
    `id`            INT UNSIGNED NOT NULL AUTO_INCREMENT,
    `setting_key`   VARCHAR(100) NOT NULL,
    `setting_value` TEXT,
    `setting_group` VARCHAR(50)  DEFAULT NULL,
    `description`   VARCHAR(255) DEFAULT NULL,
    `updated_at`    DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`),
    UNIQUE KEY `uk_settings_key` (`setting_key`),
    KEY `idx_settings_group` (`setting_group`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ============================================================================
-- END OF SCHEMA
-- ============================================================================


