-- --- departments -------------------------------------------------------------
INSERT INTO `departments` (id, slug, name, abbreviation, tagline, intro, vision, mission, hod_name, hod_title, hod_message, research, contact_email, contact_phone, is_published, sort_order) VALUES (1, 'accountancy', 'Department of Accountancy', 'DoA', 'Pioneers of business education at Wayamba University', 'The Department of Accountancy at Wayamba University of Sri Lanka has played a pioneering role in business education since the establishment of the University in 2001, being one of the earliest academic disciplines introduced. At present, the Department offers the B.Sc in Accountancy and Business Finance degree, designed to meet the evolving demands of the accounting and business environment. The degree programme is structured into three key academic clusters — Accountancy, Business Finance, and Accounting Information Systems — designed to provide students with a comprehensive and industry-relevant education.', 'An Assured future for all Sri Lankans and a prosperous society through learning', 'The department will ensure the provision of high-quality accountancy education and training towards optimum utilization, control and development of resources that; raise achievement reduces disparity leads to opportunities', NULL, 'Message from the Head of the Department', 'The Department is strongly committed to delivering high-quality accounting education with a holistic approach to developing competent and ethical business professionals. Our academic staff comprise well-qualified scholars with doctoral training, relevant industry experience, and professional credentials in accountancy and related fields. They actively engage in research across diverse areas, including financial and management accounting, auditing, financial management, accounting education, taxation, and corporate governance. Our teaching and learning practices emphasize strong theoretical foundations, professional competencies, and innovative pedagogical approaches. The accounting programmes offered by the Department are accredited by leading professional bodies such as the Association of Chartered Certified Accountants (ACCA), the Chartered Institute of Management Accountants (CIMA), the Institute of Chartered Accountants of Sri Lanka (CA Sri Lanka), and the Institute of Certified Management Accountants (CMA). These accreditations enhance the professional recognition and career prospects of our graduates. Graduates of the Department are well prepared to serve in managerial and professional capacities across a wide range of organizations, including accounting and auditing firms, financial institutions, corporate entities, government bodies, and non-profit organizations, both in Sri Lanka and beyond.', 'Academic staff actively engage in research across diverse areas, including financial and management accounting, auditing, financial management, accounting education, taxation, and corporate governance. The department publishes the Journal of Accountancy & Finance (JAF) and the open-access Journal of SACFIRE, and participates in the SACFIRE symposium and the faculty-level JARSYM journal.', NULL, NULL, 1, 1);
INSERT INTO `departments` (id, slug, name, abbreviation, tagline, intro, vision, mission, hod_name, hod_title, hod_message, research, contact_email, contact_phone, is_published, sort_order) VALUES (2, 'banking-finance', 'Department of Banking and Finance', 'DoBF', 'Pioneer in banking and finance education in Sri Lanka', 'The Department of Banking & Finance is one of the pioneer academic departments in the Faculty of Business Studies and Finance, which offers the B.Sc Banking and Finance (Special) degree programme every year to the undergraduates of the faculty since 2001. The Department of Banking and Finance is committed to providing a well-rounded banking and finance education and co-curricular experience to all its students. The department is basically focused on the subject areas of Economics, Bank Management, Investments, Financial Markets and Institutions. The primary focus of the department is to enhance undergraduate and postgraduate learning and knowledge by teaching particularly in Banking & Finance and technology, and in close association with industry and commerce.', 'To be the center of excellence in banking and finance education and research in Sri Lanka.', 'To achieve excellence in the diffusion of knowledge relate to Banking and Financial services in line with the best practices for the field of Banking and Finance', 'Mr. AGDLK Gunaratna', 'Message from the Head of the Department', 'The Department of Banking & Finance is the pioneer department to offer a specialized degree in Banking & Finance in Sri Lanka. Bachelor of Science (Special) Degree in Banking & Finance is a four-year duration programme conducted in English medium offered with the objective of providing a sound academic & professional background in Banking & Finance enabling the graduates to learn a wide array of subjects from the areas of Banking & Finance. The department is offering students an outcome-based education through outcome-based teaching and learning process to develop their personal capabilities, discipline-specific competencies, professional, ethical and social attributes in order to become a skilled graduate who can compete in the global context. The department focuses on the holistic development of undergraduates by a combination of both curricular and extracurricular activities. Apart from the curriculum, the department provides the opportunity for students to follow several certificate courses developed to improve their soft skills, language fluency and research competencies. The department has partnered with many reputed banks and financial institutions enabling students to gain the opportunity to expose to real-world, by completing a comprehensive internship programme of six months during the degree programme. The department staff comprises many PhD qualified academics and well-experienced staff in the discipline of Banking & Finance. The entire fraternity of the Department of Banking & Finance cohesively works and commits towards the accomplishment of its mission of achieving excellence as a department in the arena of Banking and Finance.', 'The department publishes the Sri Lankan Journal of Banking and Finance (SLJBF) and organizes the annual Symposium in Banking & Finance (SyBFin). Faculty are PhD-qualified academics and industry practitioners engaged in banking, finance and economics research.', NULL, NULL, 1, 2);
INSERT INTO `departments` (id, slug, name, abbreviation, tagline, intro, vision, mission, hod_name, hod_title, hod_message, research, contact_email, contact_phone, is_published, sort_order) VALUES (3, 'business-management', 'Department of Business Management', 'DoBM', 'Management education from diploma to masters', 'The Department of Business Management offers the Postgraduate Diploma in Business Management (PGDBM) leading to the Masters Degree in Business Administration (MBA). The department advertises a new intake for the PGDBM programme and publishes programme details through the faculty website. (The source document does not provide further narrative about the department; details are added as documented.)', NULL, NULL, NULL, 'Message from the Head of the Department', 'The source document does not include a message from the Head of the Department of Business Management. Further information is required.', 'The source document does not provide details of research activities for this department.', NULL, NULL, 1, 3);
INSERT INTO `departments` (id, slug, name, abbreviation, tagline, intro, vision, mission, hod_name, hod_title, hod_message, research, contact_email, contact_phone, is_published, sort_order) VALUES (4, 'insurance-valuation', 'Department of Insurance and Valuation', 'DoIV', 'Pioneer academic center in risk and insurance education', 'The Department of Insurance and Valuation is committed to enhance the education in the field of Insurance and Finance by introducing undergraduate, diploma and higher diploma programmes with skills, capabilities and competencies to meet the real world requirement through interaction with public and private sector organizations. It is also committed to pursuing the excellence in teaching and learning in Insurance and Finance by conducting research and community service while making all efforts to contribute to the vision of the Faculty of Business Studies and Finance. At present, the Department is successfully conducting undergraduate, Higher Diploma, Diploma, and Certificate programmes for internal and external students, and planned to commence the postgraduate degree programme specific to Risk Management and Insurance.', 'To be the Centre of Excellence in the Arena of Risk and Insurance Education.', 'Department of Insurance and Valuation is committed to develop its stakeholders'' competencies through education, training, research, and other outreach programmes to more effectively manage the challenges in the field of risk, insurance and finance.', 'Dr. Weedige Sampath Sanjeewa', 'Message from the Head of the Department', 'It is with much pleasure I welcome you to the official website of the Department of Insurance and Valuation, the pioneer academic center in risk and insurance education in Sri Lanka. The Department of Insurance and Valuation of the Wayamba University of Sri Lanka is committed to enhancing education in the field of Risk, Insurance, and Finance by introducing undergraduate, diploma, and higher diploma programmes with skills, capabilities and competencies to meet the real-world requirement through interaction with public and private sector organizations. It is also committed to pursuing excellence in teaching and learning in Risk, Insurance, and Finance by conducting research and community service while making all efforts to contribute to the vision of the Faculty of Business Studies and Finance. Bachelor of Science Honours in Insurance & Finance is the main degree programme offered to the internal undergraduates of the department and the curriculum of the degree is designed to provide a sound academic & professional background in Risk Management & Insurance, and Finance Services enabling the graduate to secure a wide range of job opportunities and professional developments. The department is offering students an outcome-based education through outcome-based teaching and learning processes to develop their capabilities, discipline-specific competencies, and professional, ethical and social attributes to become skilled graduates who can compete in the global context. The department has partnered with leading Insurance and Financial Services Companies in Sri Lanka enabling students to gain the opportunity to expose to real-world, by completing a comprehensive internship programme of six months during the degree programme. To meet the requirements of the insurance industry in Sri Lanka, we are successfully conducting external academic programmes for employees who are working in the insurance industry in Sri Lanka. Our academic staffs have received doctoral training with relevant work experience in Risk management, Insurance, Financial services related fields, and most have professional qualifications in the discipline of insurance and finance. They are actively involved in research, with interests in risk management, insurance, and financial services.', 'The department publishes the Journal of Insurance & Finance (JIF) — a refereed, semi-annual journal — and the biannual magazine Voice of Insurance. Academic staff hold doctoral training with research interests in risk management, insurance, and financial services.', NULL, NULL, 1, 4);

