INSERT INTO `programmes` (id, slug, name, category_id, department_id, summary, description, duration, credits, fees, deadline, deadline_status, application_contact, entry_requirements, highlights, document_note, is_published, sort_order) VALUES (1, 'bsc-accountancy-business-finance', 'B.Sc. in Accountancy and Business Finance', NULL, 1, 'Undergraduate degree structured into three academic clusters: Accountancy, Business Finance and Accounting Information Systems.', 'The B.Sc in Accountancy and Business Finance degree is designed to meet the evolving demands of the accounting and business environment. The degree programme is structured into three key academic clusters — Accountancy, Business Finance, and Accounting Information Systems — designed to provide students with a comprehensive and industry-relevant education. The programme is accredited by leading professional bodies (ACCA, CIMA, CA Sri Lanka and CMA).', 'Information not available in the source document', 'Information not available in the source document', 'Information not available in the source document', NULL, 'historical', 'Contact the faculty office for current intake information.', NULL, NULL, 'Application forms and documents can be requested from the faculty office.', 1, 1);
INSERT INTO `programmes` (id, slug, name, category_id, department_id, summary, description, duration, credits, fees, deadline, deadline_status, application_contact, entry_requirements, highlights, document_note, is_published, sort_order) VALUES (2, 'bsc-banking-finance', 'B.Sc. Banking and Finance (Special)', NULL, 2, 'Four-year specialized degree in banking and finance, taught in English with a six-month industry internship.', 'Bachelor of Science (Special) Degree in Banking & Finance is a four-year duration programme conducted in English medium offered with the objective of providing a sound academic & professional background in Banking & Finance enabling the graduates to learn a wide array of subjects from the areas of Banking & Finance. The department offers outcome-based education through outcome-based teaching and learning processes to develop personal capabilities, discipline-specific competencies, professional, ethical and social attributes in order to become a skilled graduate who can compete in the global context.', 'Four years', 'Information not available in the source document', 'Information not available in the source document', NULL, 'historical', 'Contact the faculty office for current intake information.', NULL, NULL, 'Application forms and documents can be requested from the faculty office.', 1, 2);
INSERT INTO `programmes` (id, slug, name, category_id, department_id, summary, description, duration, credits, fees, deadline, deadline_status, application_contact, entry_requirements, highlights, document_note, is_published, sort_order) VALUES (3, 'bsc-honours-insurance-finance', 'B.Sc. (Honours) in Insurance & Finance', NULL, 4, 'Main degree of the pioneer center in risk and insurance education, with a six-month industry internship.', 'Bachelor of Science Honours in Insurance & Finance is the main degree programme offered to the internal undergraduates of the Department of Insurance and Valuation. The curriculum is designed to provide a sound academic & professional background in Risk Management & Insurance, and Finance Services enabling the graduate to secure a wide range of job opportunities and professional developments. The department offers outcome-based education through outcome-based teaching and learning processes.', 'Information not available in the source document', 'Information not available in the source document', 'Information not available in the source document', NULL, 'historical', 'Contact the faculty office for current intake information.', NULL, NULL, 'Application forms and documents can be requested from the faculty office.', 1, 3);
INSERT INTO `programmes` (id, slug, name, category_id, department_id, summary, description, duration, credits, fees, deadline, deadline_status, application_contact, entry_requirements, highlights, document_note, is_published, sort_order) VALUES (4, 'pgdbm', 'Postgraduate Diploma in Business Management (PGDBM)', NULL, 3, 'One-year postgraduate diploma with twelve taught modules and a project report, leading to the MBA.', 'The Postgraduate Diploma in Business Management (PGDBM) is a programme of study which will run through one academic year (approximately one calendar year duration). Participants will follow twelve course modules during the period, of which all course modules will be compulsory. Each course module will be of about 30 hours of teaching. The academic year comprises two terms; twelve courses are taught during this period. In addition, every participant should complete a project report and submit the same at the end of the 2nd term of the Programme. Those who complete all the requirements of the PGDBM may be admitted to the 2nd year of the Programme — the Masters Degree in Business Administration.', 'One year (12 months); minimum period of study one year, maximum allowed five years', '24 credits (course modules including the project report, Year One)', 'Information not available in the source document', 'Applications closing date: extended to 22 December 2023', 'historical', 'Contact the faculty office for current intake information.', 'Detailed entry requirements were not provided in the source document.
Selection for the MBA (second year) is based on merits and availability of placements; a limited number of participants are also selected under the ‘Direct Entrance’ criteria (candidates possessing qualifications equal to the PGDBM of Wayamba University of Sri Lanka).', NULL, 'Application forms and documents can be requested from the faculty office.', 1, 4);
INSERT INTO `programmes` (id, slug, name, category_id, department_id, summary, description, duration, credits, fees, deadline, deadline_status, application_contact, entry_requirements, highlights, document_note, is_published, sort_order) VALUES (5, 'mba', 'Masters Degree in Business Administration (MBA)', NULL, 3, 'Second academic year of the PGDBM-to-MBA programme: two taught courses plus a comprehensive research thesis.', 'The Masters Degree in Business Administration (MBA) is the second academic year of the total programme. The participants devote their full time to complete management research under the guidance of supervisors appointed by the University. They may attend a series of advanced seminars and lectures organized by the Faculty of Business Studies & Finance. Participants must earn a total of sixteen (16) credits by following two taught courses (08 credits) and completing a comprehensive Research Thesis (08 credits).', 'One academic year (second year of the programme)', '16 credits — two taught courses (08 credits) plus comprehensive research thesis (08 credits)', 'Information not available in the source document', NULL, 'historical', 'Contact the faculty office for current intake information.', 'Completion of all requirements of the Postgraduate Diploma in Business Management (PGDBM), or
Direct Entrance: candidates possessing qualifications equal to the PGDBM of Wayamba University of Sri Lanka may be selected directly to the MBA programme.
Selection is based on merits and availability of placements.', NULL, 'Application forms and documents can be requested from the faculty office.', 1, 5);
INSERT INTO `programmes` (id, slug, name, category_id, department_id, summary, description, duration, credits, fees, deadline, deadline_status, application_contact, entry_requirements, highlights, document_note, is_published, sort_order) VALUES (6, 'dais', 'Diploma in Accounting Information Systems (DAIS)', 3, 1, 'One-year diploma (30 credits) delivered on weekends, addressing the national need for Accounting Information Systems education.', 'Having identified the mounting demand for Accounting Information Systems related study courses and with the industry reputation gained through intense collaborations, the Department of Accountancy believes that it has a responsibility to continue upgrading knowledge and educating people who engage in the field of Accounting Information Systems. The Department offers the Diploma in Accounting Information Systems (DAIS) to address the national need of people who have not reached higher education in this field and wish to proceed with this discipline. Lectures will be held on weekends.', 'One academic year consisting of two semesters (weekends)', '30 credits required for completion of the course', 'Rs. 80,000.00 total — Rs. 40,000.00 at registration; balance in two instalments of Rs. 20,000.00 each during the course.', 'Application deadline extended to: 25 January 2024', 'historical', 'Contact the faculty office for current intake information.', 'Passed G.C.E Advanced Level in any stream, OR
Passed AAT second Level, OR
Passed ICASL executive Level, OR
Passed CIMA 1st Level, OR
Passed CMA 1st Level, OR
Passed ACCA 1st Level, OR
Qualifications other than those listed above may be acceptable case by case subject to the approval of the Board of Study.
On acceptance by the Board of Study, a person shall forthwith register as a Diploma Student of the university upon payment of prescribed registration and other fees.', NULL, 'Application forms and documents can be requested from the faculty office.', 1, 6);
INSERT INTO `programmes` (id, slug, name, category_id, department_id, summary, description, duration, credits, fees, deadline, deadline_status, application_contact, entry_requirements, highlights, document_note, is_published, sort_order) VALUES (7, 'dbfs', 'Diploma in Banking and Financial Studies (DBFS)', 3, 2, 'One-year external diploma (30 credits, SLQF Level 3) designed to meet the demands of the flourishing banking and financial sector.', 'Today, the banking and financial sector is flourishing in our country and requires more employees and professionals to meet the demand. Having identified the expected qualities and competencies required for the financial sector, the Department of Banking and Finance — the pioneer in banking and finance education provider in Sri Lanka — has designed its external programmes to cope up with the challenge. The Diploma in Banking and Financial Studies (DBFS) facilitates learning in theory and practices to improve skills in advanced areas of economics, banking and finance and equips students with an integrated approach to managerial skills. The course units are designed to develop analytical, problem-solving and decision-making abilities, awareness of domestic and international economics and financial environment.', 'One year, consisting of two semesters', '30 credits of course units (SLQF Level 3)', 'Rs. 65,000 total — Rs. 30,000 at registration; balance in two instalments during the first semester before the semester examination.', 'Closing date of applications: 10th May 2025 (Extended)', 'historical', 'Contact the faculty office or the Department of Banking and Finance for current intake information.', 'Passed in G.C.E (A/L) examination in any stream in a single attempt, OR
Six passes in G.C.E (O/L) Examination in one sitting with three credits with two years working experience in a reputed institution after obtaining the qualification, OR
Any other qualification not listed above with two years working experience, may be considered case by case and acceptable to the Board of Study and the Senate of WUSL;
A good knowledge of English;
Perform well at the admission test and/or the interview.', NULL, 'Application forms and documents can be requested from the faculty office.', 1, 7);
INSERT INTO `programmes` (id, slug, name, category_id, department_id, summary, description, duration, credits, fees, deadline, deadline_status, application_contact, entry_requirements, highlights, document_note, is_published, sort_order) VALUES (8, 'hdbfs', 'Higher Diploma in Banking and Financial Studies (HDBFS)', 4, 2, 'Flagship one-year higher diploma (30 credits, SLQF Level 4) developing future-ready banking professionals.', 'Step into the world of banking and finance with the Higher Diploma in Banking and Financial Studies (HDBFS), a flagship programme offered by the Department of Banking and Finance, Faculty of Business Studies and Finance, Wayamba University of Sri Lanka. The programme is designed to meet the growing demand for skilled professionals in Sri Lanka''s vibrant financial services sector. Through a blend of academic theory and practical learning, the HDBFS develops future-ready banking professionals with the knowledge, skills, and confidence to excel in an ever-evolving financial landscape.', 'One (01) year, consisting of two semesters', '30 credits of course units (SLQF Level 4)', 'Rs. 90,000 total — Rs. 40,000 at registration; balance in two instalments during the first semester before the semester examination.', 'Closing date: 25th February 2026', 'historical', 'Ms. HMAK Herath (Director) — 037 228 4216 / 071 757 4114; Mr. AGDLK Gunaratna (Academic Coordinator) — 071 582 2953; Email: hdbfs@wyb.ac.lk', 'A Diploma in Banking and Financial Studies (DBFS) offered by the Department of Banking and Finance, Wayamba University of Sri Lanka, OR
A recognized Diploma (minimum 30 credits) in management, banking, or finance from a reputed institution, OR
G.C.E (A/L) qualification in any stream (in one sitting), plus a Certificate in Banking and Finance (CBF) or Intermediate in Applied Banking and Finance (IABF) from the Institute of Bankers of Sri Lanka, with at least three years of executive-level experience in a reputed organization, OR
Other qualifications approved on a case-by-case basis by the University Senate.', NULL, 'Application forms and documents can be requested from the faculty office.', 1, 8);
INSERT INTO `programmes` (id, slug, name, category_id, department_id, summary, description, duration, credits, fees, deadline, deadline_status, application_contact, entry_requirements, highlights, document_note, is_published, sort_order) VALUES (9, 'acfsm', 'Advanced Certificate in Financial Services Management (ACFSM)', 5, 2, 'First advanced certificate programme of its nature offered by the department under its external programmes (SLQF Level 2).', 'The Department of Banking and Finance is one of the prominent departments in the Sri Lankan university system to cater needs of the Banking & financial industry. The introduction of this nature of course was a long-felt need of the Industry as there are no advanced certificate programmes offered by any university related to this discipline. Further, many employees in the banking and financial services sector are engaged in their work without theoretical background related to their employment. The Department of Banking and Finance considered this vacuum and decided to introduce this Advanced Certificate programme with the aim of infusing enthusiasm among potential people who are eager to solve problems they encountered while in the service. This is the first Advanced Certificate programme introduced by the Department of this nature under its external programmes. Financial firms, on the other hand, could monitor this programme and embody this into their promotion schemes too. The programme is designed following the requirements of the Sri Lanka Qualification Framework (SLQF) Level 2.', 'Information not available in the source document', 'Information not available in the source document', 'Information not available in the source document', 'New application date: 25th March 2025 (Extended)', 'historical', 'Contact the faculty office or the Department of Banking and Finance for current intake information.', 'Main objective: to endow a person with a generalized knowledge, skills, attitudes and competencies which are essential to begin a career in the Financial Service Industry.
Target group, programme duration, admission requirement, method of delivery and commencement details were presented in the source document''s programme table and require confirmation with the department.', NULL, 'Application forms and documents can be requested from the faculty office.', 1, 9);
INSERT INTO `programmes` (id, slug, name, category_id, department_id, summary, description, duration, credits, fees, deadline, deadline_status, application_contact, entry_requirements, highlights, document_note, is_published, sort_order) VALUES (10, 'dip-hdip-rmi', 'Diploma & Higher Diploma in Risk Management & Insurance', 3, 4, 'External academic programmes conducted for employees working in the insurance industry in Sri Lanka.', 'To meet the requirements of the insurance industry in Sri Lanka, the Department of Insurance and Valuation successfully conducts external academic programmes for employees who are working in the insurance industry in Sri Lanka. The department advertised a new intake in 2023 for its Diploma & Higher Diploma programmes. Detailed course structures, fees and entry requirements were not included in the source document and require confirmation with the department.', 'Information not available in the source document', 'Information not available in the source document', 'Information not available in the source document', NULL, 'historical', 'Contact the faculty office or the Department of Insurance and Valuation for current intake information.', 'Entry requirements were not provided in the source document.', NULL, 'Application forms and documents can be requested from the faculty office.', 1, 10);

