-- --- journals -------------------------------------------------------------
INSERT INTO `journals` (id, slug, abbreviation, name, type, publisher, issn, frequency, description, submission_guidelines, submission_email, latest_issue, is_published, sort_order) VALUES (1, 'jarsym', 'JARSYM', 'Journal of Annual Research Symposium in Management (JARSYM)', 'Journal (Refereed)', 'Faculty of Business Studies and Finance, Wayamba University of Sri Lanka', 'Information not available in the source document', 'Bi-annually', 'A publication of Students'' Research of the Annual Research Symposium in Management. The Journal of ARSYM (JARSYM) is a refereed journal published bi-annually by the Faculty of Business Studies & Finance, Wayamba University of Sri Lanka. The aim of the JARSYM is to disseminate high-quality research findings on a variety of timely topics generated by undergraduate researchers at the Wayamba University of Sri Lanka. Furthermore, it opens up avenues for undergraduates involved in the industry to share their inventions, state-of-the-art discoveries, and novel ideas. The main philosophy behind the JARSYM is to enhance the research culture within the faculty, thereby within Wayamba University. All research articles submitted are double-blind reviewed prior to publishing. Views expressed in the research articles are not the views of the Faculty of Business Studies and Finance, Wayamba University of Sri Lanka, or the Editorial Board.', 'Submission and editorial contact details were not provided in the source document.', NULL, 'Volume 05 — Issue I (July 2025)', 1, 1);
INSERT INTO `journals` (id, slug, abbreviation, name, type, publisher, issn, frequency, description, submission_guidelines, submission_email, latest_issue, is_published, sort_order) VALUES (2, 'jaf', 'JAF', 'Journal of Accountancy and Finance (JAF)', 'Journal (Refereed)', 'Department of Accountancy, Faculty of Business Studies and Finance, Wayamba University of Sri Lanka', 'Information not available in the source document', 'Biannually', 'The Journal of Accountancy and Finance is biannually published by the Department of Accountancy, Faculty of Business Studies and Finance, Wayamba University of Sri Lanka. The main objective of the journal is to publish scientific research findings that address issues and development related to the Accounting and Finance Industry, particularly at both the national and international levels. Initially issued as an Accountancy Journal for six volumes since July 2004; in 2014 the journal was renamed the Journal of Accountancy and Finance and recognized as a refereed journal, published biannually. The journal provides a worthwhile platform for academics spread out within the country as well as globally to publish their novel research work in the field of Accountancy and Finance.', 'Full papers are to be submitted to jaf@wyb.ac.lk. Manuscripts must be sent in MS Word (Doc/Docx) format. The full paper should not exceed 30 pages (B5 size) including references and appendices, and must contain: Title, Abstract, Keywords, Introduction, Literature Review, Methodology, Results and Discussion, Conclusion, and References. The acceptable range of the Similarity Index is up to 20 percent. Submissions must be original works that have not been accepted for publication/presentation or are under review anywhere else. Authors may submit multiple papers.', NULL, 'JAF Volume 12 — Issue I (2025)', 1, 2);
INSERT INTO `journals` (id, slug, abbreviation, name, type, publisher, issn, frequency, description, submission_guidelines, submission_email, latest_issue, is_published, sort_order) VALUES (3, 'sacfire', 'SACFIRE', 'Journal of SACFIRE', 'Journal (Open Access)', 'Department of Accountancy, Wayamba University of Sri Lanka', 'Information not available in the source document', 'Annually (print and online)', 'Journal of SACFIRE is a scholarly journal that publishes articles from the discipline of accounting and finance. It is an open-access journal which abides by internationally accepted research and publication ethics, and is funded, hosted and published by the Department of Accountancy, Wayamba University of Sri Lanka, Sri Lanka. The journal provides a forum for undergraduates of Sri Lanka to exchange information, debate, and disseminate knowledge in various areas of accounting and finance. The journal is steered by an independent editorial board that consists of members nominated by the Department of Accountancy and approved by the faculty board of the Faculty of Business Studies and Finance.', 'Submission and editorial contact details were not provided in the source document.', NULL, 'Volume 03 — Issue I', 1, 3);
INSERT INTO `journals` (id, slug, abbreviation, name, type, publisher, issn, frequency, description, submission_guidelines, submission_email, latest_issue, is_published, sort_order) VALUES (4, 'sljbsf', 'SLJBSF', 'Sri Lankan Journal of Business Studies and Finance (SLJBSF)', 'Journal (Double-blind peer-reviewed)', 'Faculty of Business Studies and Finance, Wayamba University of Sri Lanka', '2756-9381', 'Semi-annually', 'The Sri Lankan Journal of Business Studies and Finance (SLJBSF) is a double-blind peer-reviewed scholarly journal which aims to publish scholarly work in the field of Business Studies & Finance. It is published semi-annually by the Faculty of Business Studies and Finance, Wayamba University of Sri Lanka. The objectives of the SLJBSF are three folds: (i) to benchmark the Faculty’s contribution for the growth of the body of knowledge in Business Studies & Finance; (ii) to promote and provide convenient access to publish and disseminate the research works of potential researchers/scholars; and (iii) to maintain the Faculty journal as an updated channel to provide solutions for unsolved problems while maintaining academic excellence in knowledge dissemination in the field. The journal is addressed to diverse communities, including academics, professionals, graduate and postgraduate students, and anyone with a keen interest in the field of Business Studies & Finance. The Faculty planned to publish Volume I, Issue I of SLJBSF in March 2021.', 'Submission e-mail: sljbsf@wyb.ac.lk. Authors are advised to read aims and scope and author guidelines when preparing a manuscript and submit it when it is at a publishable level.', NULL, 'Volume I — Issue 2', 1, 4);
INSERT INTO `journals` (id, slug, abbreviation, name, type, publisher, issn, frequency, description, submission_guidelines, submission_email, latest_issue, is_published, sort_order) VALUES (5, 'sljbf', 'SLJBF', 'Sri Lankan Journal of Banking and Finance (SLJBF)', 'Journal (Double-blind peer-reviewed)', 'Department of Banking and Finance, Wayamba University of Sri Lanka', '2345-9271', 'Bi-annually', 'The Sri Lankan Journal of Banking and Finance (SLJBF) is an official double-blind peer-reviewed journal that publishes research papers and scholarly work by the Department of Banking and Finance, Wayamba University of Sri Lanka. SLJBF publishes theoretical and empirical papers spanning all the major research fields in economics, banking and finance. The aim of the SLJBF is to bridge the gap existing in the theory and practice of Economics, Banking and Finance by encouraging researchers, academicians, professionals, and research students to impart and share knowledge in the form of high-quality research papers to infuse innovative systems and methods to the economic and financial system as a whole.', 'Papers may be submitted as hard copy or by e-mail (soft copy in Word and PDF format with a covering letter including author’s details). Manuscripts for publishing considerations should be sent to: Chief Editor, Sri Lankan Journal of Banking and Finance, Department of Banking and Finance, Wayamba University of Sri Lanka, Kuliyapitiya, Sri Lanka. Tel: (+94) 037-2284216. Email: sljbf@wyb.ac.lk or sljbf.ce@gmail.com. The journal gives priority to novelty, originality, and the extent of contribution to the banking industry. Each manuscript is sent to two reviewers.', NULL, 'Vol 8 — Issue I (June 2025) — call for papers', 1, 5);
INSERT INTO `journals` (id, slug, abbreviation, name, type, publisher, issn, frequency, description, submission_guidelines, submission_email, latest_issue, is_published, sort_order) VALUES (6, 'jif', 'JIF', 'Journal of Insurance & Finance (JIF)', 'Journal (Refereed)', 'Department of Insurance and Valuation, Faculty of Business Studies and Finance, Wayamba University of Sri Lanka', 'ISSN (Print): 2673-1258 / ISSN (Online): 2773-7276', 'Semi-annually (January / July)', 'The Journal of Insurance & Finance is a refereed journal, published semi-annually (January/July) by the Department of Insurance and Valuation, Faculty of Business Studies and Finance, Wayamba University of Sri Lanka. This journal publishes empirical research and review papers in the areas of Insurance, Risk Management, Finance, Management, Economics, and Social Security. The fundamental objective of the journal is to disseminate the knowledge of research conducted by academics, and professionals/practitioners in the field of Insurance and Finance. The Department of Insurance and Valuation intends to publish the journal with effect from January 2021.', 'Submission e-mail: jif@wyb.ac.lk. Authors are advised to read aims and scope and author guidelines when preparing a manuscript and submit it when it is at a publishable level.', NULL, 'JIF Volume 2 — Issue 2', 1, 6);
INSERT INTO `journals` (id, slug, abbreviation, name, type, publisher, issn, frequency, description, submission_guidelines, submission_email, latest_issue, is_published, sort_order) VALUES (7, 'voice of insurance', 'Voice of Insurance', 'Voice of Insurance', 'Magazine (Biannual)', 'Department of Insurance and Valuation, Wayamba University of Sri Lanka', 'ISSN: 2806-5018 / ISBN: 9772806 501005', 'Biannual', 'The Voice of Insurance is the biannual specialized magazine published by the Department of Insurance and Valuation of the Wayamba University of Sri Lanka. The Voice of Insurance provides a trustful and independent information platform for the stakeholders of the risk & insurance business in Sri Lanka. The magazine aims to enlighten the sphere of risk and insurance with its latest trends, information, strategies, and insights to mitigate the dynamism of the business environment. Even though there are many institutions and professionals connected to the risk & insurance business, there is no common platform to present their professional voices, information, experience, and expectations; the Voice of Insurance aims to fill that gap by connecting the stakeholders in the insurance business in Sri Lanka and expects to create a trustful information source for the industry.', 'Submission guidelines were referenced in the source document; contact the Department of Insurance and Valuation via the faculty office for details.', NULL, 'Current themed volume', 1, 7);

