-- --- events -------------------------------------------------------------
INSERT INTO `events` (id, slug, event_type_id, edition, name, organiser, theme, description, status, submission_info, contact, keynote_name, keynote_details, is_published, sort_order) VALUES (1, 'arsym-2024', 1, 'arsym-2024', 'ARSYM 2024', 'Faculty of Business Studies and Finance, Wayamba University of Sri Lanka', 'Beyond Boundaries: Pioneering Management Research for Sustainable Development', 'The Faculty of Business Studies and Finance of the Wayamba University of Sri Lanka proudly invites you to the 7th Annual Research Symposium in Management — ARSYM 2024, which aims at providing a platform for undergraduates and academics to exchange and share their experience and research on all aspects of Management.', 'concluded', 'Registration and submission links were provided with the symposium announcement; see the faculty office for current details.', NULL, 'Prof. Ravi Dissanayake', 'PhD (Taylor – Malaysia), DBA (Switzerland), MBA (PIM), B.B Mgt. (Kelaniya). Professor in Marketing, University of Kelaniya.', 1, 1);
INSERT INTO `events` (id, slug, event_type_id, edition, name, organiser, theme, description, status, submission_info, contact, keynote_name, keynote_details, is_published, sort_order) VALUES (2, 'sacfire-2025', 1, 'sacfire-2025', 'SACFIRE 2025', 'Department of Accountancy, Faculty of Business Studies and Finance, Wayamba University of Sri Lanka', 'Furtherance of Entrepreneurialism Culture through Interdisciplinary Research Paradigm in Longitudinality', 'SACFIRE 2025 is the 11th consecutive research symposium organized by the Department of Accountancy, Faculty of Business Studies and Finance, Wayamba University of Sri Lanka. The symposium proposed to expand its scope to provide a platform for local and international young researchers to showcase their research findings, and aims to foster collaboration and strengthen the network among young researchers and experts in the field of Accounting & Finance, both from the local and international communities. Registration is free.', 'concluded', 'Email: sacfire@wyb.ac.lk · Tel: +37 22 84214. Extended abstract and full paper submission links were provided with the symposium announcement.', NULL, 'Prof. Lakshman R. Watawala', 'Founder and President – CMA Sri Lanka; Past President CA Sri Lanka.', 1, 2);
INSERT INTO `events` (id, slug, event_type_id, edition, name, organiser, theme, description, status, submission_info, contact, keynote_name, keynote_details, is_published, sort_order) VALUES (3, 'sybfin-2025', 1, 'sybfin-2025', 'SyBFin 2025', 'Department of Banking & Finance, Wayamba University of Sri Lanka', 'Redesigning Finance for an Intelligent, Inclusive Future', 'The Department of Banking & Finance, Wayamba University of Sri Lanka, proudly presents the 2nd Symposium in Banking & Finance. This annual academic gathering serves as a dynamic platform for undergraduates, researchers, and academics to exchange ideas, share experiences, and present research findings on a wide range of topics related to Banking and Finance. By fostering dialogue and collaboration, the symposium aims to inspire innovation, encourage critical thinking, and strengthen the link between academic knowledge and industry practice in the ever-evolving financial sector.', 'concluded', 'Submission guidelines and templates were provided with the symposium announcement; see the faculty office for current details.', NULL, 'Mr. Dilan Wijerathne', 'Head of Innovations, Hatton National Bank PLC.', 1, 3);

