INSERT INTO `news` (id, slug, news_type, category_id, title, body, status, is_archived, published_at, sort_order) VALUES (1, 'announcement-1', 'announcement', 1, 'HDBFS applications closing date: 25 February 2026', 'Applications are called for the Higher Diploma in Banking and Financial Studies (HDBFS) offered by the Department of Banking and Finance. Closing date (as documented): 25th February 2026. Contact: hdbfs@wyb.ac.lk — Ms. HMAK Herath (Director) 037 228 4216 / 071 757 4114.', 'published', 1, NULL, 1);
INSERT INTO `news` (id, slug, news_type, category_id, title, body, status, is_archived, published_at, sort_order) VALUES (2, 'announcement-2', 'announcement', 1, 'DBFS applications closing date: 10 May 2025 (Extended)', 'Applications are called for the Diploma in Banking and Financial Studies (DBFS). Closing date (as documented): 10th May 2025, extended. Downloadable documents: Application Form; Brochure DBFS 2022.', 'published', 1, NULL, 2);
INSERT INTO `news` (id, slug, news_type, category_id, title, body, status, is_archived, published_at, sort_order) VALUES (3, 'announcement-3', 'announcement', 1, 'Advanced Certificate in Financial Services Management — new application date', 'Applications are called for the Advanced Certificate in Financial Services Management (ACFSM) offered by the Department of Banking and Finance. New application date (as documented): 25th March 2025, extended.', 'published', 1, NULL, 3);
INSERT INTO `news` (id, slug, news_type, category_id, title, body, status, is_archived, published_at, sort_order) VALUES (4, 'announcement-4', 'announcement', 1, 'DAIS application deadline extended to 25 January 2024', 'Applications for the Diploma in Accounting Information Systems (DAIS), Department of Accountancy. Lectures are held on weekends. Application deadline (as documented): extended to 25 January 2024.', 'published', 1, NULL, 4);
INSERT INTO `news` (id, slug, news_type, category_id, title, body, status, is_archived, published_at, sort_order) VALUES (5, 'announcement-5', 'announcement', 1, 'PGDBM new intake — January 2024', 'The Department of Business Management invites applications for the Postgraduate Diploma in Business Management (PGDBM) leading to the Masters Degree in Business Administration (MBA). New intake: January 2024. Closing date for applications (as documented): extended to 22 December 2023.', 'published', 1, NULL, 5);
INSERT INTO `news` (id, slug, news_type, category_id, title, body, status, is_archived, published_at, sort_order) VALUES (6, 'announcement-6', 'announcement', 3, 'SACFIRE 2025 — registration free, conference on 14 November 2025', 'The 11th Symposium of Accounting & Finance Research (SACFIRE 2025), Department of Accountancy. Registration is free. Conference date (as documented): 14 November 2025. Theme: "Furtherance of Entrepreneurialism Culture through Interdisciplinary Research Paradigm in Longitudinality".', 'published', 1, NULL, 6);
INSERT INTO `news` (id, slug, news_type, category_id, title, body, status, is_archived, published_at, sort_order) VALUES (7, 'announcement-7', 'announcement', 3, 'SyBFin 2025 — call for papers', 'The 2nd Symposium in Banking & Finance (SyBFin 2025), Department of Banking & Finance. Calling for papers from 01 August 2025; conference day 20 November 2025 (as documented). Theme: "Redesigning Finance for an Intelligent, Inclusive Future".', 'published', 1, NULL, 7);
INSERT INTO `news` (id, slug, news_type, category_id, title, body, status, is_archived, published_at, sort_order) VALUES (8, 'announcement-8', 'announcement', 3, 'ARSYM 2024 — 7th Annual Research Symposium in Management', 'The 7th Annual Research Symposium in Management (ARSYM 2024). Registration link and author guidelines were published with the announcement. Pre-conference seminar: 04 December 2024 (as documented).', 'published', 1, NULL, 8);
INSERT INTO `news` (id, slug, news_type, category_id, title, body, status, is_archived, published_at, sort_order) VALUES (9, 'announcement-9', 'announcement', 2, 'SLJBF — Call for Research Articles, Vol 8 Issue I (Jun 2025)', 'The Sri Lankan Journal of Banking and Finance (SLJBF) welcomes original research articles in English on disciplines related to economics, banking and finance at both national and international level. Submissions: sljbf@wyb.ac.lk / sljbf.ce@gmail.com, Tel (+94) 037-2284216.', 'published', 1, NULL, 9);
INSERT INTO `news` (id, slug, news_type, category_id, title, body, status, is_archived, published_at, sort_order) VALUES (10, 'announcement-10', 'announcement', 3, 'SACFIRE 2024 — 11 December 2024, 9:00 AM', 'Mark your calendars for SACFIRE 2024! Join on December 11th from 9:00 AM at the Faculty of Business Studies and Finance, Wayamba University of Sri Lanka, for the most anticipated research symposium of the year (as documented).', 'published', 1, NULL, 10);

