-- --- faqs -------------------------------------------------------------
INSERT INTO `faqs` (id, question, answer, sort_order, is_published) VALUES (1, 'Where is the Faculty of Business Studies and Finance located?', 'The faculty is located at the Kuliyapitiya premises of Wayamba University of Sri Lanka (60200, Kuliyapitiya, Sri Lanka).', 1, 1);
INSERT INTO `faqs` (id, question, answer, sort_order, is_published) VALUES (2, 'When was the faculty established?', 'The Faculty of Business Studies and Finance (FBSF) was established on 01 October 1999 by the Government Notification in the Extraordinary Gazette No. 1093/8 of Tuesday, 17 August 1999, and remains the fastest growing faculty of Wayamba University of Sri Lanka.', 2, 1);
INSERT INTO `faqs` (id, question, answer, sort_order, is_published) VALUES (3, 'How many departments does the faculty have?', 'The faculty consists of four departments of studies: Department of Accountancy, Department of Banking and Finance, Department of Business Management, and Department of Insurance and Valuation.', 3, 1);
INSERT INTO `faqs` (id, question, answer, sort_order, is_published) VALUES (4, 'What are the admission requirements for the Diploma in Accounting Information Systems (DAIS)?', 'Any one of the following: passed G.C.E Advanced Level in any stream; passed AAT second Level; passed ICASL executive Level; passed CIMA 1st Level; passed CMA 1st Level; passed ACCA 1st Level. Other qualifications may be acceptable case by case subject to approval of the Board of Study. Lectures are held on weekends.', 4, 1);
INSERT INTO `faqs` (id, question, answer, sort_order, is_published) VALUES (5, 'What are the admission routes for the Diploma in Banking and Financial Studies (DBFS)?', '(1) Passed G.C.E (A/L) examination in any stream in a single attempt; (2) Six passes in G.C.E (O/L) Examination in one sitting with three credits and two years working experience in a reputed institution; (3) Any other qualification with two years working experience, considered case by case by the Board of Study and the Senate of WUSL. A good knowledge of English and performance at the admission test/interview are required.', 5, 1);
INSERT INTO `faqs` (id, question, answer, sort_order, is_published) VALUES (6, 'How does the PGDBM lead to the MBA?', 'The Postgraduate Diploma in Business Management (PGDBM) runs for one academic year with twelve compulsory course modules (24 credits) plus a project report. Those who complete all PGDBM requirements may be admitted to the second year — the Masters Degree in Business Administration (MBA) — earning 16 credits through two taught courses (8 credits) and a comprehensive research thesis (8 credits). A limited number of direct-entrance candidates may also be admitted to the MBA.', 6, 1);
INSERT INTO `faqs` (id, question, answer, sort_order, is_published) VALUES (7, 'How do I submit a research paper to the Journal of Accountancy and Finance (JAF)?', 'Submit the full paper (maximum 30 pages, B5 size, MS Word format) to jaf@wyb.ac.lk. Papers must contain Title, Abstract, Keywords, Introduction, Literature Review, Methodology, Results and Discussion, Conclusion and References. The acceptable similarity index is up to 20 percent.', 7, 1);
INSERT INTO `faqs` (id, question, answer, sort_order, is_published) VALUES (8, 'Who can I contact for programme applications?', 'General enquiries: Faculty office — Tel +94 37 228 4215, Email bsfoffice@wyb.ac.lk. HDBFS specifically: Ms. HMAK Herath (Director) 037 228 4216 / 071 757 4114 or Mr. AGDLK Gunaratna (Academic Coordinator) 071 582 2953, hdbfs@wyb.ac.lk. Journal submissions: jaf@wyb.ac.lk, sljbsf@wyb.ac.lk, sljbf@wyb.ac.lk, jif@wyb.ac.lk. SACFIRE: sacfire@wyb.ac.lk, +37 22 84214.', 8, 1);

